-- stg_mp_packages_intransit: 160 rows. NOT APPLIED, branch only.
-- Licence from the FILENAME - this grid export carries no title block and no
-- licence column, so no in-file confirmation is possible. Stated, not implied.
create table if not exists public.stg_mp_packages_intransit (
  tag text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  licence_evidence text not null,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mp_packages_intransit enable row level security;
drop policy if exists stg_mp_packages_intransit_read on public.stg_mp_packages_intransit;
create policy stg_mp_packages_intransit_read on public.stg_mp_packages_intransit for select to authenticated using (true);
